{
  "project_id": "fc8763e72e094009a03e",
  "name": "create_analytics_read_only_role",
  "query": "do $$
begin
  if not exists (select 1 from pg_roles where rolname = 'analytics') then
    create role analytics no login inherit;
  else
    alter role analytics no login inherit;
  end if;
end
$$;

-- Allow the role to resolve objects in the application schema, but not create objects.
grant usage on schema public to analytics;
revoke create on schema public from analytics;

-- Read-only access to existing application tables and views.
revoke all privileges on all tables in schema public from analytics;
grant select on all tables in schema public to analytics;

-- Preserve the read-only access for tables created by the project owner.
alter default privileges for role postgres in schema public
  revoke insert, update, delete, truncate, references, trigger on tables from analytics;
alter default privileges for role postgres in schema public
  grant select on tables to analytics;"
}

